from django.db import models
class WorkflowFact(models.Model):tenant_key=models.CharField(max_length=100,db_index=True);workflow_key=models.CharField(max_length=100,db_index=True);instance_id=models.CharField(max_length=100);status=models.CharField(max_length=30);started_at=models.DateTimeField();completed_at=models.DateTimeField(null=True);duration_seconds=models.BigIntegerField(null=True);sla_breached=models.BooleanField(default=False);total_cost=models.DecimalField(max_digits=14,decimal_places=2,null=True);dimensions=models.JSONField(default=dict);loaded_at=models.DateTimeField(auto_now_add=True)
class StateDurationFact(models.Model):tenant_key=models.CharField(max_length=100,db_index=True);workflow_key=models.CharField(max_length=100);instance_id=models.CharField(max_length=100);state_key=models.CharField(max_length=100);entered_at=models.DateTimeField();exited_at=models.DateTimeField(null=True);duration_seconds=models.BigIntegerField(null=True);dimensions=models.JSONField(default=dict)
